"""Mascara e-mails pessoais numa transcrição .jsonl e soma os tokens do campo usage.

uso: python -I sessao.py tokens <arquivo.jsonl>
     python -I sessao.py mascarar <entrada.jsonl> <saida.jsonl> <email> [<email> ...]
"""
import json
import sys
from datetime import datetime, timedelta, timezone

BRT = timezone(timedelta(hours=-3))


def tokens(path):
    usages, models, stamps = {}, set(), []
    with open(path, encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            rec = json.loads(line)
            if rec.get("timestamp"):
                stamps.append(rec["timestamp"])
            msg = rec.get("message")
            if rec.get("type") != "assistant" or not isinstance(msg, dict) or "usage" not in msg:
                continue
            if msg.get("model", "").startswith("<"):
                continue
            models.add(msg.get("model"))
            usages[msg.get("id") or rec.get("uuid")] = msg["usage"]  # streaming: fica a última
    keys = ["input_tokens", "output_tokens", "cache_creation_input_tokens", "cache_read_input_tokens"]
    tot = [sum(u.get(k, 0) or 0 for u in usages.values()) for k in keys]
    to_brt = lambda s: datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(BRT)
    ini, fim = to_brt(min(stamps)), to_brt(max(stamps))
    print(f"inicio {ini:%d/%m %H:%M}  fim {fim:%H:%M}  modelos {sorted(models)}")
    print("input {:,} | output {:,} | cache escrita {:,} | cache leitura {:,} | total {:,}".format(*tot, sum(tot)))


import re

EMAIL = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.(?:com|br|org|net|io|edu|dev|local)\b")
PERMITIDOS = re.compile(
    r"^(noreply@anthropic\.com|[^@]+@users\.noreply\.github\.com"
    r"|[^@]+@(trim\.com|teste\.com|trim\.local|example\.com))$"
)


def _walk(o, fn):
    if isinstance(o, str):
        return fn(o)
    if isinstance(o, list):
        return [_walk(x, fn) for x in o]
    if isinstance(o, dict):
        return {k: _walk(v, fn) for k, v in o.items()}
    return o


def mascarar(src, dst, _extra=()):
    """Mascara e-mails pessoais dentro das strings do JSON já interpretado (os escapes não quebram).

    1ª passada: e-mails completos. 2ª: a parte local desses e-mails onde mais aparecer
    (por exemplo, dentro de um padrão de sed como usuario@gmail\.com)."""
    locais, contagem = set(), {}

    def coleta(texto):
        for m in EMAIL.finditer(texto):
            if not PERMITIDOS.match(m.group(0)):
                locais.add(m.group(0).split("@")[0])
        return texto

    linhas = [json.loads(l) for l in open(src, encoding="utf-8") if l.strip()]
    for rec in linhas:
        _walk(rec, coleta)
    locais = sorted((x for x in locais if len(x) >= 5), key=len, reverse=True)
    padrao_local = re.compile("|".join(re.escape(x) for x in locais)) if locais else None

    def troca(m):
        if PERMITIDOS.match(m.group(0)):
            return m.group(0)
        dom = m.group(0).split("@")[1]
        contagem[dom] = contagem.get(dom, 0) + 1
        return "[email-removido]"

    def limpa(texto):
        texto = EMAIL.sub(troca, texto)
        if padrao_local:
            texto, n = padrao_local.subn("[email-removido]", texto)
            contagem["(parte local)"] = contagem.get("(parte local)", 0) + n
        return texto

    nl = chr(10)
    with open(dst, "w", encoding="utf-8", newline=nl) as out:
        for rec in linhas:
            out.write(json.dumps(_walk(rec, limpa), ensure_ascii=False, separators=(",", ":")) + nl)
    print("mascarados:", contagem)


if __name__ == "__main__":
    if sys.argv[1] == "tokens":
        tokens(sys.argv[2])
    else:
        mascarar(sys.argv[2], sys.argv[3], sys.argv[4:])

